<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\TemplateVariable\Application\Usecase\Disable;

use Psr\EventDispatcher\EventDispatcherInterface;
use Throwable;
use Civi\Lughauth\Shared\Security\Allow;
use Civi\Lughauth\Shared\Exception\UnauthorizedException;
use Civi\Lughauth\Shared\Exception\NotFoundException;
use Civi\Lughauth\Features\Document\TemplateVariable\Domain\TemplateVariableRef;
use Civi\Lughauth\Features\Document\TemplateVariable\Application\Service\Visibility\TemplateVariableVisibilityService;
use Civi\Lughauth\Features\Document\TemplateVariable\Domain\Gateway\TemplateVariableWriteGateway;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class TemplateVariableDisableUsecase
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly EventDispatcherInterface $dispatcher,
        private readonly TemplateVariableVisibilityService $visibility,
        private readonly TemplateVariableWriteGateway $writer,
    ) {
    }

    public function allowDisable(?TemplateVariableRef $ref = null): Allow
    {
        $this->logDebug("Check allow of Disable usecase for Template variable");
        $span = $this->startSpan("Check allow of Disable usecase for Template variable");
        try {
            $result = $this->dispatcher->dispatch(new TemplateVariableDisableAllowDecision(Allow::allowed('disable', 'Allowed to Template variable by default')));
            return $result->getAllow();
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function disable(string $uid): TemplateVariableDisableResult
    {
        $this->logDebug("Run Disable usecase for Template variable");
        $span = $this->startSpan("Run Disable usecase for Template variable");
        try {
            $ref = new TemplateVariableRef($uid);
            $allow = $this->allowDisable($ref);
            if (!$allow->allowed) {
                throw new UnauthorizedException($allow->reason ?? 'Not allowed to Disable Template variable');
            }
            if (!$original = $this->visibility->retrieveVisibleForUpdate($ref)) {
                throw new NotFoundException($uid);
            }
            $this->dispatcher->dispatch(new TemplateVariableDisableCheck($original));
            $modified = $original->disable();
            $result = $this->writer->update($original, $modified);
            $output = $this->visibility->copyWithHidden($this->visibility->prepareVisibleData($result));
            return new TemplateVariableDisableResult($output);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
